import pytest
from solution import iso_week

# Correctness on year boundaries where ISO year differs from calendar year
def test_iso_year_boundary_start():
    # 2014-12-29 is Monday and belongs to ISO week 1 of 2015
    assert iso_week("2014-12-29") == "2015-W01"

def test_iso_year_boundary_end():
    # 2015-12-31 is Thursday and belongs to ISO week 53 of 2015
    assert iso_week("2015-12-31") == "2015-W53"

def test_iso_week_number_two_digits():
    # Week 1 should be zero‑padded
    assert iso_week("2022-01-03") == "2022-W01"
    # Week 10 should not be padded extra
    assert iso_week("2022-03-07") == "2022-W10"

def test_leap_day_valid():
    # 2020 is a leap year
    assert iso_week("2020-02-29") == "2020-W09"

def test_non_leap_feb_29_invalid():
    with pytest.raises(ValueError):
        iso_week("2019-02-29")

def test_invalid_month():
    with pytest.raises(ValueError):
        iso_week("2022-13-01")

def test_invalid_day():
    with pytest.raises(ValueError):
        iso_week("2022-04-31")  # April has 30 days

def test_year_zero_rejected():
    with pytest.raises(ValueError):
        iso_week("0000-01-01")

def test_negative_year_format_rejected():
    with pytest.raises(ValueError):
        iso_week("-001-01-01")

def test_non_string_input():
    with pytest.raises(ValueError):
        iso_week(20220101)

def test_whitespace_handling():
    # Leading/trailing spaces should be stripped and still work
    assert iso_week(" 2022-01-03 ") == "2022-W01"

def test_extra_internal_spaces():
    # Internal spaces break the format
    with pytest.raises(ValueError):
        iso_week("2022- 01-03")

def test_invalid_format_missing_dash():
    with pytest.raises(ValueError):
        iso_week("20220103")

def test_invalid_format_extra_characters():
    with pytest.raises(ValueError):
        iso_week("2022-01-03T00:00:00")

def test_maximum_supported_date():
    # datetime supports up to year 9999
    assert iso_week("9999-12-31") == "9999-W52"

def test_minimum_supported_date():
    # Earliest valid ISO date (year 1)
    assert iso_week("0001-01-01") == "0001-W01"

def test_date_on_iso_week_boundary_end_of_year():
    # 2020-12-31 is Thursday, belongs to week 53 of 2020
    assert iso_week("2020-12-31") == "2020-W53"

def test_date_on_iso_week_boundary_start_of_year():
    # 2021-01-01 is Friday, still week 53 of 2020
    assert iso_week("2021-01-01") == "2020-W53"

def test_invalid_day_zero():
    with pytest.raises(ValueError):
        iso_week("2022-05-00")

def test_invalid_month_zero():
    with pytest.raises(ValueError):
        iso_week("2022-00-10")

import datetime
import pytest
from solution import iso_week

# ---------- Valid date edge cases ----------
def test_iso_week_year_boundary_start():
    # 2021-01-01 is in ISO week 53 of 2020
    assert iso_week("2021-01-01") == "2020-W53"

def test_iso_week_year_boundary_end():
    # 2020-12-31 is also in ISO week 53 of 2020
    assert iso_week("2020-12-31") == "2020-W53"

def test_iso_week_leap_day():
    # 2020-02-29 is week 9 of 2020
    assert iso_week("2020-02-29") == "2020-W09"

def test_iso_week_last_day_of_year_non_leap():
    # 2019-12-31 is week 1 of 2020
    assert iso_week("2019-12-31") == "2020-W01"

def test_iso_week_last_day_of_year_leap():
    # 2016-12-31 is week 52 of 2016
    assert iso_week("2016-12-31") == "2016-W52"

def test_iso_week_week_53_exists():
    # 2015 had week 53, check a date in that week
    assert iso_week("2015-12-31") == "2015-W53"

def test_iso_week_week_53_nonexistent():
    # 2014 had no week 53, 2014-12-31 is week 1 of 2015
    assert iso_week("2014-12-31") == "2015-W01"

def test_iso_week_whitespace_stripping():
    # Leading/trailing spaces should be ignored
    assert iso_week(" 2022-03-15 ") == "2022-W11"

def test_iso_week_maximum_supported_year():
    # datetime supports up to year 9999
    assert iso_week("9999-12-31") == datetime.date(9999,12,31).isocalendar()[0:2][0:2][0]  # just ensure no exception

# ---------- Invalid inputs ----------
def test_iso_week_non_string():
    with pytest.raises(TypeError):
        iso_week(20220101)  # int, not str

def test_iso_week_bytes_input():
    with pytest.raises(TypeError):
        iso_week(b"2022-01-01")

def test_iso_week_empty_string():
    with pytest.raises(TypeError):
        iso_week("")

def test_iso_week_wrong_separator():
    with pytest.raises(TypeError):
        iso_week("2022/01/01")

def test_iso_week_missing_leading_zeros():
    with pytest.raises(TypeError):
        iso_week("2022-1-1")

def test_iso_week_extra_characters():
    with pytest.raises(TypeError):
        iso_week("2022-01-01abc")

def test_iso_week_internal_whitespace():
    with pytest.raises(TypeError):
        iso_week("2022- 01-01")

def test_iso_week_invalid_month_zero():
    with pytest.raises(TypeError):
        iso_week("2022-00-10")

def test_iso_week_invalid_month_thirteen():
    with pytest.raises(TypeError):
        iso_week("2022-13-10")

def test_iso_week_invalid_day_zero():
    with pytest.raises(TypeError):
        iso_week("2022-01-00")

def test_iso_week_invalid_day_thirty_two():
    with pytest.raises(TypeError):
        iso_week("2022-01-32")

def test_iso_week_invalid_feb_29_non_leap():
    with pytest.raises(TypeError):
        iso_week("2021-02-29")

def test_iso_week_year_zero():
    with pytest.raises(TypeError):
        iso_week("0000-01-01")

def test_iso_week_negative_year():
    with pytest.raises(TypeError):
        iso_week("-2022-01-01")

def test_iso_week_invalid_format_too_long():
    with pytest.raises(TypeError):
        iso_week("2022-001-01")

def test_iso_week_invalid_format_too_short():
    with pytest.raises(TypeError):
        iso_week("22-01-01")
